  function castleLocal(x,y){return {x:(x-WINTER_CASTLE.x)/WINTER_CASTLE.width*1536,y:(y-WINTER_CASTLE.y)/WINTER_CASTLE.height*1024};}
  function castleBehindFoot(x,y){const p=castleLocal(x,y);return activeMapId==='winterbach'&&p.x>=0&&p.x<=1536&&p.y>=0&&p.y<512;}
  const CASTLE_ROAD=Object.freeze([[1035,660],[1130,691],[1260,722],[1390,745],[1535,752]].map(([x,y])=>Object.freeze([WINTER_CASTLE.x+x/1536*WINTER_CASTLE.width,WINTER_CASTLE.y+y/1024*WINTER_CASTLE.height])));
  function castleRoadContains(x,y){
    if(x<CASTLE_ROAD[0][0]||x>CASTLE_ROAD.at(-1)[0]+15)return false;
    return closestPointOnBridgePath(x,y,CASTLE_ROAD).distance<=WINTER_CASTLE.width/1536*(26+12*clamp((x-CASTLE_ROAD[0][0])/(CASTLE_ROAD.at(-1)[0]-CASTLE_ROAD[0][0]),0,1));
  }
  function castleBlockedFoot(x,y){
    if(activeMapId!=='winterbach')return false;
    const p=castleLocal(x,y);
    if(p.x<0||p.x>=1536||p.y<512||p.y>=1024||castleRoadContains(x,y))return false;
    return CASTLE_ALPHA[Math.floor(p.y/1024*256)*384+Math.floor(p.x/1536*384)]===1;
  }
  function tryCastleRoad(player,dx,dy=0){
    if(activeMapId!=='winterbach'||(!dx&&!dy)||!castleRoadContains(player.x,player.y))return null;
    const p=closestPointOnBridgePath(player.x,player.y,CASTLE_ROAD);
    if(p.progress>=.995&&dx>0)return null;
    return {id:'castle-road',path:CASTLE_ROAD,distance:p.pathDistance,snapping:true,snapRate:7};
  }
  function moveCastleRoad(player,road,dx,dt){
    const anchor=pointAtBridgeDistance(road.path,road.distance);
    if(road.snapping){
      const d=Math.hypot(anchor.x-player.x,anchor.y-player.y);
      if(d>2){const blend=1-Math.exp(-7*dt);player.x+=(anchor.x-player.x)*blend;player.y+=(anchor.y-player.y)*blend;return road;}
      player.x=anchor.x;player.y=anchor.y;road.snapping=false;
    }
    if(!dx)return road;
    const total=getPathMetrics(road.path).total;
    road.distance=clamp(road.distance+Math.sign(dx)*PLAYER.speed*dt,0,total);
    Object.assign(player,pointAtBridgeDistance(road.path,road.distance));
    // Left stop is the outside of the palisade. Only the right road end releases.
    if(road.distance>=total-.001&&dx>0){player.x+=2;return null;}
    return road;
  }
